"""IAM HTTP API: project two approved, versioned JSON manifests into metadata.

Standalone Lambda module; no source CPU/model imports or mutable latest lookup.
Only the packaged approved_artifacts.json controls S3 keys and versions.
"""

from datetime import datetime
import hashlib
import json
import logging
import math
import os
from pathlib import Path
import re
import uuid

ROUTES = {"GET /datasets", "GET /prompts", "GET /evaluations/{evaluation_id}"}
LIMITATIONS = [
    "Historical outputs; no new predictions generated by this deployment.",
    "Immutable generating model and adapter revisions are unavailable.",
    "Benchmark subsets do not establish full-held-out model accuracy.",
    "The newly registered CPU prompt was not used for historical generation.",
    "No controlled fine-tuning comparison or new latency benchmark is established.",
]


class RequestError(Exception):
    def __init__(self, status, message):
        self.status, self.message = status, message


def require(condition, message):
    if not condition:
        raise ValueError(message)


def mapping(value):
    return value if isinstance(value, dict) else {}


def reply(status, body):
    return {
        "statusCode": status,
        "headers": {
            "content-type": "application/json", "cache-control": "no-store",
            "x-content-type-options": "nosniff",
        },
        "isBase64Encoded": False,
        "body": json.dumps(body, allow_nan=False, separators=(",", ":")),
    }


def request_route(event, expected_api_id, approved):
    event = mapping(event)
    context = mapping(event.get("requestContext"))
    iam = mapping(mapping(context.get("authorizer")).get("iam"))
    arn = iam.get("userArn")
    if (not expected_api_id or context.get("apiId") != expected_api_id
            or not isinstance(arn, str) or not arn.startswith("arn:aws:")):
        raise RequestError(403, "Forbidden")
    if event.get("version") != "2.0":
        raise RequestError(400, "Unsupported request format")
    route = event.get("routeKey")
    if not isinstance(route, str) or route not in ROUTES:
        raise RequestError(404, "Route not found")
    if mapping(context.get("http")).get("method") != "GET":
        raise RequestError(405, "Only GET is supported")
    if event.get("queryStringParameters") or event.get("rawQueryString") or event.get("body"):
        raise RequestError(400, "Query parameters and request bodies are not supported")
    if route == "GET /evaluations/{evaluation_id}":
        value = mapping(event.get("pathParameters")).get("evaluation_id")
        try:
            if not isinstance(value, str) or str(uuid.UUID(value)) != value:
                raise ValueError("Invalid evaluation UUID")
        except (ValueError, AttributeError):
            raise RequestError(400, "Invalid evaluation ID") from None
        if value != approved["evaluation"]["evaluation_id"]:
            raise RequestError(404, "Evaluation not found")
    return route


def unique_pairs(pairs):
    result = {}
    for key, value in pairs:
        require(key not in result, "Duplicate JSON key")
        result[key] = value
    return result


def invalid_constant(_value):
    raise ValueError("Non-finite JSON number")


def parse_json(body):
    return json.loads(body, object_pairs_hook=unique_pairs, parse_constant=invalid_constant)


def read_manifest(s3, approved, name):
    identity = approved[name]
    size = identity["bytes"]
    require(type(size) is int and 0 < size <= 64 * 1024, "Manifest size outside limits")
    response = s3.get_object(
        Bucket=approved["bucket"], Key=identity["key"], VersionId=identity["version_id"]
    )
    body = response["Body"]
    chunks, length = [], 0
    try:
        require(response.get("VersionId") == identity["version_id"]
                and response.get("ServerSideEncryption") == "AES256"
                and response.get("ContentLength") == size,
                "Manifest S3 identity differs")
        metadata = mapping(response.get("Metadata"))
        require(metadata.get("source-commit") == identity["source_commit"]
                and metadata.get("sha256") == identity["sha256"], "Manifest metadata differs")
        while True:
            chunk = body.read(min(64 * 1024, size + 1 - length))
            if not chunk:
                break
            length += len(chunk)
            require(length <= size, "Manifest body exceeds limit")
            chunks.append(chunk)
    finally:
        body.close()
    payload = b"".join(chunks)
    require(length == size and hashlib.sha256(payload).hexdigest() == identity["sha256"],
            "Manifest body checksum differs")
    document = parse_json(payload)
    require(isinstance(document, dict), "Manifest must be an object")
    require(
        document.get("schema_version") == identity["schema_version"]
        and document.get("operation") == identity["operation"]
        and document.get("source_commit") == identity["source_commit"]
        and document.get("build_id") == identity["build_id"]
        and document.get("bucket") == approved["bucket"]
        and document.get("prefix") == identity["prefix"]
        and document.get("status") == "ARTIFACTS_VERIFIED"
        and document.get("required_build_status") == "SUCCEEDED"
        and document.get("registration_scope") == "versioned_s3_manifest"
        and document.get("live_inference") is False,
        "Manifest producer identity differs",
    )
    timestamp = document.get("created_at")
    require(isinstance(timestamp, str)
            and datetime.fromisoformat(timestamp).utcoffset() is not None,
            "Invalid manifest timestamp")
    return document


def hash_value(value):
    require(isinstance(value, str) and re.fullmatch(r"[0-9a-f]{64}", value), "Invalid digest")
    return value


def positive_integer(value):
    require(type(value) is int and value > 0, "Expected a positive integer")
    return value


def artifact_reference(document, approved, name, filename):
    item = document["artifacts"][filename]
    require(isinstance(item, dict)
            and item.get("key") == approved[name]["prefix"] + filename
            and item.get("encryption") == "AES256", "Unexpected artifact reference")
    version = item.get("version_id")
    require(isinstance(version, str) and version not in ("", "null"), "Missing artifact version")
    return {
        "key": item["key"], "version_id": version, "sha256": hash_value(item.get("sha256")),
        "bytes": positive_integer(item.get("bytes")), "encryption": "AES256",
    }


def provenance(document, approved, name):
    identity = approved[name]
    return {
        "build_id": identity["build_id"], "source_commit": identity["source_commit"],
        "created_at": document["created_at"], "bucket": approved["bucket"],
        "manifest": {
            "key": identity["key"], "version_id": identity["version_id"],
            "sha256": identity["sha256"], "bytes": identity["bytes"], "encryption": "AES256",
        },
        "approval": "Previously verified successful producer build; approved immutable snapshot",
    }


def dataset_metadata(document, approved):
    counts = approved["catalog"]["expected_documents"]
    require(set(document.get("splits", {})) == set(counts), "Unexpected dataset splits")
    checks = document.get("checks")
    require(isinstance(checks, dict)
            and set(checks) == {
                "canonical_hypotheses", "expected_counts", "split_id_and_exact_text_disjoint",
                "tracked_train_validation_semantic_match",
            } and all(value is True for value in checks.values()), "Dataset checks are incomplete")
    upstream = document["upstream"]
    require(upstream.get("dataset_source") == "https://stanfordnlp.github.io/contract-nli/"
            and upstream.get("dataset_license") == "CC BY 4.0", "Dataset attribution differs")
    datasets = []
    for split, expected in counts.items():
        metadata = document["splits"][split]
        documents = positive_integer(metadata.get("documents"))
        rows = positive_integer(metadata.get("input_rows"))
        require(documents == expected and rows == 17 * documents, "Dataset counts differ")
        processed = artifact_reference(document, approved, "catalog", split + ".jsonl")
        source = artifact_reference(document, approved, "catalog", "source-" + split + ".json")
        require(processed["sha256"] == hash_value(metadata.get("output_sha256"))
                and source["sha256"] == hash_value(metadata.get("source_sha256")),
                "Dataset artifact digests differ")
        if split == "test":
            require(all(processed[field] == approved["reference_test"][field]
                        for field in ("key", "version_id", "sha256", "bytes")),
                    "Test artifact differs from the approved evaluation reference")
        datasets.append({
            "split": split, "documents": documents, "input_rows": rows,
            "semantic_sha256": hash_value(metadata.get("semantic_sha256")),
            "held_out": split == "test", "processed_artifact": processed, "source_artifact": source,
        })
    return {
        "api_schema_version": "contractnli-artifact-api-v1",
        "operation": "list_registered_datasets", "live_inference": False,
        "catalog": provenance(document, approved, "catalog"),
        "dataset_source": upstream["dataset_source"], "dataset_license": upstream["dataset_license"],
        "checks": dict(checks), "datasets": datasets,
    }


def prompt_metadata(document, approved):
    prompt = document["prompt"]
    artifact = artifact_reference(document, approved, "catalog", "prompt.json")
    require(prompt.get("name") == "contract_extractor_cpu_v1"
            and prompt.get("model_binding") is None
            and prompt.get("file") == "prompt.json"
            and hash_value(prompt.get("sha256")) == artifact["sha256"], "Prompt identity differs")
    return {
        "api_schema_version": "contractnli-artifact-api-v1",
        "operation": "list_registered_prompts", "live_inference": False,
        "catalog": provenance(document, approved, "catalog"),
        "prompts": [{
            "name": prompt["name"], "sha256": artifact["sha256"], "model_binding": None,
            "artifact": artifact, "generation_validation": "No new model execution in this deployment",
        }],
    }


def probability(value):
    require(type(value) in (float, int) and math.isfinite(value) and 0 <= value <= 1,
            "Invalid metric probability")
    return value


def evaluation_metadata(document, approved):
    require(document.get("evaluation_kind") == "historical_benchmark_replay"
            and document.get("historical_source_commit")
            == approved["evaluation"]["historical_source_commit"], "Evaluation source differs")
    reference = document["reference"]
    expected = approved["reference_test"]
    require(reference.get("bucket") == approved["bucket"]
            and all(reference.get(field) == expected[field]
                    for field in ("key", "version_id", "sha256", "bytes", "documents")),
            "Evaluation reference differs")
    groups = document.get("groups")
    require(isinstance(groups, dict) and set(groups) == {"4_client", "7_client"},
            "Unexpected evaluation groups")
    exposed = {}
    for name, group in groups.items():
        result = {}
        for field in (
            "requests", "scored_requests", "missing_requests", "invalid_requests",
            "unique_input_contracts", "matched_reference_records", "recorded_transport_failures",
        ):
            value = group.get(field)
            require(type(value) is int and value >= 0, "Invalid request count")
            result[field] = value
        require(result["requests"] > 0
                and result["requests"] == sum(result[field] for field in (
                    "scored_requests", "missing_requests", "invalid_requests"
                )) and 0 < result["unique_input_contracts"] <= result["requests"]
                and result["unique_input_contracts"] <= result["matched_reference_records"]
                <= expected["documents"]
                and result["recorded_transport_failures"] <= result["requests"],
                "Inconsistent evaluation accounting")
        for field in (
            "request_label_accuracy_all_attempts", "first_attempt_label_accuracy_all_attempts",
            "reference_subset_fraction",
        ):
            result[field] = probability(group.get(field))
        require(math.isclose(result["reference_subset_fraction"],
                             result["matched_reference_records"] / expected["documents"],
                             rel_tol=0, abs_tol=1e-12), "Invalid subset coverage")
        exposed[name] = result
    return {
        "api_schema_version": "contractnli-artifact-api-v1",
        "operation": "get_registered_evaluation", "live_inference": False,
        "evaluation_id": approved["evaluation"]["evaluation_id"],
        "evaluation_kind": "historical_benchmark_replay",
        "status": "ARTIFACTS_VERIFIED", "evaluation": provenance(document, approved, "evaluation"),
        "historical_source_commit": approved["evaluation"]["historical_source_commit"],
        "reference": {field: expected[field] for field in (
            "key", "version_id", "sha256", "bytes", "documents"
        )},
        "groups": exposed,
        "artifacts": {
            filename: artifact_reference(document, approved, "evaluation", filename)
            for filename in ("report.json", "attempts.jsonl")
        },
        "limitations": list(LIMITATIONS),
    }


def handle_request(event, *, expected_api_id, approved, s3_factory):
    try:
        route = request_route(event, expected_api_id, approved)
    except RequestError as exc:
        return reply(exc.status, {"error": exc.message})
    try:
        name = "evaluation" if route == "GET /evaluations/{evaluation_id}" else "catalog"
        document = read_manifest(s3_factory(), approved, name)
        projector = {
            "GET /datasets": dataset_metadata,
            "GET /prompts": prompt_metadata,
            "GET /evaluations/{evaluation_id}": evaluation_metadata,
        }[route]
        return reply(200, projector(document, approved))
    except Exception as exc:
        logging.getLogger(__name__).error("Artifact metadata lookup failed (%s)", type(exc).__name__)
        return reply(503, {"error": "Artifact metadata is temporarily unavailable"})


def lambda_handler(event, _context):
    def s3_factory():
        import boto3
        from botocore.config import Config
        config = Config(connect_timeout=2, read_timeout=2, retries={"total_max_attempts": 2})
        return boto3.client("s3", region_name="us-east-1", config=config)

    approved = parse_json(Path(__file__).with_name("approved_artifacts.json").read_bytes())
    return handle_request(
        event, expected_api_id=os.environ["HTTP_API_ID"], approved=approved, s3_factory=s3_factory
    )
